/* clear segments */
static void s0_do_clear_segments(void)
{
    /* A Bausatz multimeter (HU-050 class), stage one: the measuring core. */
    /* Three modes on the 3-digit display, cycled by the MODE button with a */
    /* buzzer chirp: */
    /*   mode 0  volts through the 30k/10k divider      -> "X.YZ" (dp lit) */
    /*   mode 1  milliamps via 0.02R shunt + LM358 x46  -> whole mA */
    /*   mode 2  NTC via B-equation piecewise map       -> "XY.Z" degC */
    /*            (dp on the middle digit; sub-zero shows "-XY" whole degrees */
    /*            with segment g as the minus sign) */
    P0_0 = 0;
    P0_1 = 0;
    P0_2 = 0;
    P0_3 = 0;
    P0_4 = 0;
    P0_5 = 0;
    P0_6 = 0;
    P0_7 = 0;
}

/* render digit */
static void s0_do_render_digit(long n)
{
    if ((n == 0)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_4 = 1;
        P0_5 = 1;
    }
    if ((n == 1)) {
        P0_1 = 1;
        P0_2 = 1;
    }
    if ((n == 2)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_3 = 1;
        P0_4 = 1;
        P0_6 = 1;
    }
    if ((n == 3)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_6 = 1;
    }
    if ((n == 4)) {
        P0_1 = 1;
        P0_2 = 1;
        P0_5 = 1;
        P0_6 = 1;
    }
    if ((n == 5)) {
        P0_0 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_5 = 1;
        P0_6 = 1;
    }
    if ((n == 6)) {
        P0_0 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_4 = 1;
        P0_5 = 1;
        P0_6 = 1;
    }
    if ((n == 7)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_2 = 1;
    }
    if ((n == 8)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_4 = 1;
        P0_5 = 1;
        P0_6 = 1;
    }
    if ((n == 9)) {
        P0_0 = 1;
        P0_1 = 1;
        P0_2 = 1;
        P0_3 = 1;
        P0_5 = 1;
        P0_6 = 1;
    }
    if ((n == 10)) {
        P0_6 = 1;
    }
}

