static unsigned int bw_task1_state;
static unsigned int bw_task1_until;
/* when green flag clicked (script 2) */
static void bw_task1(void)
{
    switch (bw_task1_state) {
    case 0:
    mode = 0;
    lastBtn = 0;
    bw_task1_state = 1;
    case 1:
    /* the MODE button, edge-detected, with a chirp */
    if ((!P3_2 > 0)) {
        if ((lastBtn == 0)) {
            mode += 1;
            if ((mode > 2)) {
                mode = 0;
            }
            P5_5 = 0;
            bw_task1_until = bw_now() + (30);
            bw_task1_state = 2;
            case 2:
            if ((int)(bw_now() - bw_task1_until) < 0) return;
            P5_5 = 1;
        }
        lastBtn = 1;
    } else {
        lastBtn = 0;
    }
    /* take the reading for the current mode */
    if ((mode == 0)) {
        /* pin sees V/4; show centivolts as X.YZ */
        mv = ((adc_read(0) * 5000) / 1023);
        cand = ((mv * 4) / 10);
        dpDig = 0;
        showMinus = 0;
    }
    if ((mode == 1)) {
        /* LM358 output = shunt mV x 46.5; I = shunt mV x 50 */
        mv = ((adc_read(1) * 5000) / 1023);
        cand = ((mv * 50) / 47);
        dpDig = 9;
        showMinus = 0;
    }
    if ((mode == 2)) {
        /* NTC B-equation (B=3950, 10k at 25C, 10k to GND) as a piecewise */
        /* linear map over the divider millivolts; t10 = deci-degC. The */
        /* anchors are monotonic in mv, so each IF simply overwrites the */
        /* previous segment - the last match wins, no ELSE chain needed. */
        mv = ((adc_read(2) * 5000) / 1023);
        t10 = (mv - 433);
        t10 = ((t10 * 100) / 300);
        t10 = (t10 - 200);
        if ((mv > 733)) {
            t10 = (mv - 733);
            t10 = ((t10 * 100) / 413);
            t10 = (t10 - 100);
        }
        if ((mv > 1146)) {
            t10 = (mv - 1146);
            t10 = ((t10 * 100) / 511);
        }
        if ((mv > 1657)) {
            t10 = (mv - 1657);
            t10 = ((t10 * 100) / 562);
            t10 = (t10 + 100);
        }
        if ((mv > 2219)) {
            t10 = (mv - 2219);
            t10 = ((t10 * 100) / 553);
            t10 = (t10 + 200);
        }
        if ((mv > 2772)) {
            t10 = (mv - 2772);
            t10 = ((t10 * 100) / 496);
            t10 = (t10 + 300);
        }
        if ((mv > 3268)) {
            t10 = (mv - 3268);
            t10 = ((t10 * 100) / 412);
            t10 = (t10 + 400);
        }
        if ((mv > 3680)) {
            t10 = (mv - 3680);
            t10 = ((t10 * 100) / 324);
            t10 = (t10 + 500);
        }
        if ((mv > 4004)) {
            t10 = (mv - 4004);
            t10 = ((t10 * 100) / 248);
            t10 = (t10 + 600);
        }
        if ((mv > 4252)) {
            t10 = (mv - 4252);
            t10 = ((t10 * 100) / 184);
            t10 = (t10 + 700);
        }
        if ((mv > 4436)) {
            t10 = (mv - 4436);
            t10 = ((t10 * 100) / 137);
            t10 = (t10 + 800);
        }
        if ((t10 < 0)) {
            /* sub-zero: "-XY" whole degrees, minus glyph on the left digit */
            cand = (0 - t10);
            cand = (cand / 10);
            showMinus = 1;
            dpDig = 9;
        } else {
            cand = t10;
            showMinus = 0;
            dpDig = 1;
        }
    }
    if ((cand > 999)) {
        cand = 999;
    }
    diff = (cand - shown);
    if ((diff < 0)) {
        diff = (0 - diff);
    }
    if ((diff > 1)) {
        shown = cand;
        if ((showMinus == 1)) {
            d0 = 10;
            d1 = (shown / 10);
            d2 = (shown % 10);
        } else {
            d0 = (shown / 100);
            d1 = ((shown / 10) % 10);
            d2 = (shown % 10);
        }
    }
    bw_task1_until = bw_now() + (50);
    bw_task1_state = 3;
    case 3:
    if ((int)(bw_now() - bw_task1_until) < 0) return;
    bw_task1_state = 1;
    return;
    }
    bw_task1_state = 0xFFFF;   /* ran to the end */
}

/* Register setup: ports, ADC, Timer 0. Kept out of main() so the program
 * body stands alone — a C -> blocks reader can then tell them apart. */
static void bw_setup(void)
{
    P0M1 &= ~0xFF;   /* push-pull */
    P0M0 |=  0xFF;
    P2M1 &= ~0x07;   /* push-pull */
    P2M0 |=  0x07;
    P5M1 &= ~0x20;   /* push-pull */
    P5M0 |=  0x20;
    P0_0 = 0;   /* sa off */
    P0_1 = 0;   /* sb off */
    P0_2 = 0;   /* sc off */
    P0_3 = 0;   /* sd off */
    P0_4 = 0;   /* se off */
    P0_5 = 0;   /* sf off */
    P0_6 = 0;   /* sg off */
    P0_7 = 0;   /* sdp off */
    P2_0 = 1;   /* dig0 off */
    P2_1 = 1;   /* dig1 off */
    P2_2 = 1;   /* dig2 off */
    P5_5 = 1;   /* buzz off */

    P1ASF = 0x07;                 /* analog function on P1 */
    P1M1 |=  0x07;                /* high-impedance input */
    P1M0 &= ~0x07;
    ADC_CONTR = 0xE0;              /* ADC on, fastest conversion */

    AUXR &= ~0x80;                 /* Timer 0 at FOSC/12 */
    TMOD  = (TMOD & 0xF0) | 0x01;  /* Timer 0, mode 1 */
}

void main(void)
{
    bw_setup();
    TL0 = (unsigned char)(T0_RELOAD & 0xFF);
    TH0 = (unsigned char)(T0_RELOAD >> 8);
    ET0 = 1;                       /* millisecond tick */
    EA  = 1;
    TR0 = 1;

    for (;;) {                     /* the tick keeps time; the core need not */
        unsigned int pass_ms = bw_now();
        bw_task0();
        bw_task1();
        /* Two full passes inside one millisecond: idle to the next tick
         * instead of spinning the core against it — the same contract the
         * pico and AVR targets keep, spelled in the 8051's own terms.
         * PCON.IDL stops the core; Timer 0 keeps counting and its
         * interrupt clears the bit and vectors, so bw_tick above is the
         * wake source. A pass whose work crosses the edge resets the
         * count. */
        if (bw_now() == pass_ms) { if (++bw_calm >= 2u) { bw_calm = 0u; PCON |= 0x01; } }
        else bw_calm = 0u;
    }
}
